/**
 * Sentence pack: simple verified sentences built from patterns over verified forms.
 * See ./README.md; the data is generated by tools/content/verbal/gen-sentences.ts.
 */
import type { Level, PackMeta } from '../types';
import { GLOSS_FIXES, REMOVED_SENTENCES, TAG_FIXES, UPAPADA_WORD } from './audit-overlay';
import { SENTENCE_DATA } from './data';
import type { Role, Sentence, SentenceWord } from './types';

export type { Role, Sentence, SentenceWord } from './types';

function parseWord(s: string): SentenceWord {
  const [sa = '', en = '', role = '', lemma = '', tag = ''] = s.split('|');
  return { sa, en, role: role as Role, lemma, tag };
}

function applyAudit(id: string, pattern: string, words: SentenceWord[]): SentenceWord[] {
  const gloss = GLOSS_FIXES[id];
  const upapada = UPAPADA_WORD[pattern];
  const tag = TAG_FIXES[id];
  return words.map((w, i) => {
    let out = w;
    if (gloss && i === gloss[0] && w.en === gloss[1]) out = { ...out, en: gloss[2] };
    if (upapada === i && (w.role === 'karana' || w.role === 'karma' || w.role === 'sampradana')) out = { ...out, role: 'upapada' };
    if (tag && w.sa === tag[0] && w.tag === tag[1]) out = { ...out, tag: tag[2] };
    return out;
  });
}

export const SENTENCES: readonly Sentence[] = SENTENCE_DATA.filter((r) => !REMOVED_SENTENCES.has(r.id)).map((r) => ({
  id: r.id,
  words: applyAudit(r.id, r.pattern, r.w.split(' ; ').map(parseWord)),
  en: r.en,
  level: r.level,
  topic: r.topic,
  pattern: r.pattern,
  provenance: { source: `generated from pattern '${r.pattern}' over verified forms (tools/content/verbal/gen-sentences.ts)`, verifiedBy: r.v },
}));

/** Sentences at or below the given level (cumulative). */
export function sentencesForLevel(level: Level): Sentence[] {
  return SENTENCES.filter((s) => s.level <= level);
}

/** The sentence in padaccheda form: words joined by single spaces + '।' (no sandhi; a final म् stays म्). */
export function sentenceText(s: Sentence): string {
  return s.words.map((w) => w.sa).join(' ') + '।';
}

const CONSONANT = /^[क-ह]/u;
/**
 * The same sentence with the one sandhi that ordinary printed prose (and Samskrita Bharati's
 * books) always makes: a word-final म् becomes anusvāra before a consonant (मोऽनुस्वारः 8.3.23):
 * 'बालकः पुस्तकं पठति।'. Nothing else is changed.
 */
export function sentenceTextAnusvara(s: Sentence): string {
  const out = s.words.map((w, i) => {
    const next = s.words[i + 1]?.sa;
    return next !== undefined && w.sa.endsWith('म्') && CONSONANT.test(next) ? w.sa.slice(0, -2) + 'ं' : w.sa;
  });
  return out.join(' ') + '।';
}

/** Patterns that are complete without a finite verb (नमः + caturthī). */
export const VERBLESS_PATTERNS: readonly string[] = ['namah'];
/** Patterns with a subordinate verbal (ktvā / tumun) beside the finite verb. */
export const CLAUSE_PATTERNS: readonly string[] = ['ktva', 'tumun-icchati', 'tumun-shaknoti'];

export const meta: PackMeta = {
  id: 'sentences',
  title: 'सरलवाक्यानि — simple sentences',
  version: '1.0.0',
  description: 'Simple sentences generated from grammatical patterns over verified verb and noun forms: agreement, the seven vibhaktis, tenses with time adverbs, loṭ, vidhiliṅ, ktvā / tumun clauses and adjective agreement.',
  license: 'Generated content; forms verified against ashtadhyayi.com data (use with credit) and learnsanskrit.org tables (CC0) — see README.md',
  sources: ['src/content/dhatu (verified conjugations)', 'ashtadhyayi-com/data shabda/data2.txt (declensions)', 'sanskrit/data learnsanskrit.org ending and pronoun tables (CC0)', 'hand-curated compatibility table: tools/content/verbal/sentence-lexicon.ts'],
  count: SENTENCES.length,
};
